"""Cycle region discovery for the sustainable yield report."""


def _stable_vertices(request):
    """Return every station id once, preserving input order."""
    stations = request.get("stations", [])
    order = []
    seen = set()
    for station in stations:
        if station not in seen:
            seen.add(station)
            order.append(station)
    for transition in request.get("transitions", []):
        for key in ("from", "to"):
            station = transition.get(key)
            if station is not None and station not in seen:
                seen.add(station)
                order.append(station)
    return order


def _kosaraju(n, adj, radj):
    """Return (component_of_vertex, component_count) via iterative Kosaraju."""
    visited = [False] * n
    order = []
    for start in range(n):
        if visited[start]:
            continue
        stack = [(start, 0)]
        visited[start] = True
        while stack:
            v, edge_index = stack[-1]
            if edge_index < len(adj[v]):
                w = adj[v][edge_index]
                stack[-1] = (v, edge_index + 1)
                if not visited[w]:
                    visited[w] = True
                    stack.append((w, 0))
            else:
                order.append(v)
                stack.pop()

    component = [-1] * n
    component_count = 0
    for v in reversed(order):
        if component[v] != -1:
            continue
        stack = [v]
        component[v] = component_count
        while stack:
            u = stack.pop()
            for w in radj[u]:
                if component[w] == -1:
                    component[w] = component_count
                    stack.append(w)
        component_count += 1
    return component, component_count


def reachable_cycle_regions(request):
    """Return cycle-containing SCCs and the regions reachable from each station."""
    vertices = _stable_vertices(request)
    index = {station: i for i, station in enumerate(vertices)}
    n = len(vertices)

    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    transitions = request.get("transitions", [])
    for transition in transitions:
        u = index.get(transition.get("from"))
        v = index.get(transition.get("to"))
        if u is None or v is None:
            continue
        adj[u].append(v)
        radj[v].append(u)

    component, component_count = _kosaraju(n, adj, radj)

    internal = [[] for _ in range(component_count)]
    for transition in transitions:
        u = index.get(transition.get("from"))
        v = index.get(transition.get("to"))
        if u is None or v is None:
            continue
        if component[u] == component[v]:
            internal[component[u]].append(transition)

    regions = []
    region_by_component = [-1] * component_count
    for cid in range(component_count):
        if internal[cid]:
            region_by_component[cid] = len(regions)
            regions.append({
                "stations": [s for s in vertices if component[index[s]] == cid],
                "transitions": list(internal[cid]),
            })

    condensation = [set() for _ in range(component_count)]
    for transition in transitions:
        u = index.get(transition.get("from"))
        v = index.get(transition.get("to"))
        if u is None or v is None:
            continue
        cu, cv = component[u], component[v]
        if cu != cv:
            condensation[cu].add(cv)

    reachable_regions = {}
    for cid in range(component_count):
        seen = {cid}
        stack = [cid]
        while stack:
            c = stack.pop()
            for w in condensation[c]:
                if w not in seen:
                    seen.add(w)
                    stack.append(w)
        reachable_regions[cid] = sorted(
            region_by_component[r] for r in seen if region_by_component[r] != -1
        )

    reachable = {
        station: list(reachable_regions[component[index[station]]])
        for station in vertices
    }
    return {"regions": regions, "reachable": reachable}

"""Exact maximum cycle mean of a strongly connected region."""

from fractions import Fraction


def maximum_cycle_mean(region):
    """Return [numerator, denominator] for the greatest mean-gain cycle."""
    stations = list(region.get("stations", []))
    n = len(stations)
    if n == 0:
        return [0, 1]

    index = {station: i for i, station in enumerate(stations)}
    incoming = [[] for _ in range(n)]
    for transition in region.get("transitions", []):
        u = index.get(transition.get("from"))
        v = index.get(transition.get("to"))
        if u is None or v is None:
            continue
        incoming[v].append((u, transition["gain"]))

    # f[k][v] = maximum gain of a walk of exactly k edges ending at v.
    f = [[0] * n]
    for _ in range(1, n + 1):
        previous = f[-1]
        current = [None] * n
        for v in range(n):
            best = None
            for u, gain in incoming[v]:
                value = previous[u] + gain
                if best is None or value > best:
                    best = value
            current[v] = best
        f.append(current)

    f_n = f[n]
    best_overall = None
    for v in range(n):
        if f_n[v] is None:
            continue
        best_for_v = None
        for k in range(n):
            if f[k][v] is None:
                continue
            value = Fraction(f_n[v] - f[k][v], n - k)
            if best_for_v is None or value < best_for_v:
                best_for_v = value
        if best_for_v is not None and (
            best_overall is None or best_for_v > best_overall
        ):
            best_overall = best_for_v

    if best_overall is None:
        return [0, 1]
    return [best_overall.numerator, best_overall.denominator]

from fractions import Fraction
from runtime import build, read

from .cycle_mean import maximum_cycle_mean
from .cycle_regions import reachable_cycle_regions


def transform(payload, contract):
    """Return the business report described in SPEC.md. Leave caller inputs unchanged."""
    request = payload["request"]
    cycle_info = reachable_cycle_regions(request)
    region_means = [
        maximum_cycle_mean(region) for region in cycle_info["regions"]
    ]

    sustainable = {}
    for station in request.get("stations", []):
        region_indices = cycle_info["reachable"].get(station, [])
        if not region_indices:
            sustainable[station] = None
            continue
        best = None
        for region_index in region_indices:
            numerator, denominator = region_means[region_index]
            value = Fraction(numerator, denominator)
            if best is None or value > best:
                best = value
        sustainable[station] = [best.numerator, best.denominator]

    return {"sustainable": sustainable}


def load_payload(path):
    return read(path)


def build_component(root, contract):
    return build(root, contract, transform)

